from splitting import split_evenly, AcmeError
assert split_evenly(1000, 3) == [334, 333, 333], "1000/3"
assert split_evenly(5, 5) == [1, 1, 1, 1, 1]
assert split_evenly(0, 2) == [0, 0]
assert all(isinstance(x, int) for x in split_evenly(1001, 4)), "parts must be int cents"
for bad, code in [((100, 0), "E_RANGE"), ((-1, 2), "E_NEG")]:
    try:
        split_evenly(*bad); raise SystemExit(f"no error for {bad}")
    except AcmeError as e:
        assert e.code == code, f"{bad}: code {e.code!r}, want {code}"

from terms import due_date, AcmeError
assert due_date("2026-11-02", 30) == "2026-12-02", "plain"
assert due_date("2026-11-02", 25) == "2026-11-30", "lands on 11-27 (holiday) -> rolls to Monday 11-30"
assert due_date("2026-12-01", 23) == "2026-12-28", "12-24 and 12-25 are holidays, then a weekend"
assert due_date("2026-12-01", 30) == "2027-01-04", "12-31 is a holiday, 2027-01-01 too, then a weekend"
for bad, code in [(("2026-11-02", -1), "E_RANGE"), (("2026-02-30", 5), "E_FORMAT")]:
    try:
        due_date(*bad); raise SystemExit(f"no error for {bad}")
    except AcmeError as e:
        assert e.code == code, f"{bad}: code {e.code!r}, want {code}"
